const PROFILE_REGISTRY='resume-tailor-profiles';
function getProfiles(){try{return JSON.parse(localStorage.getItem(PROFILE_REGISTRY)||'[]')}catch{return[]}}
function saveProfiles(items){localStorage.setItem(PROFILE_REGISTRY,JSON.stringify(items))}
function profileLabel(){const p=getProfiles().find(x=>x.id===PROFILE_ID);return p?.name||state.profile.name||'默认档案'}
function openProfile(id){window.open(location.origin+location.pathname+'?profile='+encodeURIComponent(id),'resume_profile_'+id)}
function renderProfiles(){const items=getProfiles(),root=document.querySelector('#profileList');document.querySelector('#currentProfileName').textContent=profileLabel();root.innerHTML=items.length?items.map(x=>`<div class="profile-card"><div><h3>${esc(x.name)}</h3><p>${esc(x.basics.target||'未填写目标方向')} · ${new Date(x.createdAt).toLocaleDateString('zh-CN')}${x.id===PROFILE_ID?' · 当前窗口':''}</p></div><div class="profile-card-actions"><button data-open-profile="${x.id}">新窗口打开</button><button class="danger" data-delete-profile="${x.id}">删除档案</button></div></div>`).join(''):'<div class="library-empty">还没有单独的人员档案。填写上方基础信息即可创建。</div>';root.querySelectorAll('[data-open-profile]').forEach(b=>b.onclick=()=>openProfile(b.dataset.openProfile));root.querySelectorAll('[data-delete-profile]').forEach(b=>b.onclick=()=>{if(b.dataset.deleteProfile===PROFILE_ID)return toast('不能在当前窗口删除正在使用的档案');if(!confirm('删除后，该人员的事实库与简历历史将无法恢复。确定删除吗？'))return;const id=b.dataset.deleteProfile;saveProfiles(getProfiles().filter(x=>x.id!==id));localStorage.removeItem('resume-tailor-v2:'+id);renderProfiles()})}
const profileDialog=document.querySelector('#profileManager');document.querySelector('#openProfiles').onclick=()=>{renderProfiles();profileDialog.showModal()};document.querySelector('.close-profile-dialog').onclick=()=>profileDialog.close();profileDialog.addEventListener('click',e=>{if(e.target===profileDialog)profileDialog.close()});document.querySelector('#newProfileForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget)),id='person_'+Date.now().toString(36),person={id,name:data.name.trim(),basics:{name:data.name.trim(),target:data.target.trim(),phone:data.phone.trim(),email:data.email.trim(),location:data.location.trim(),degree:data.degree.trim()},createdAt:new Date().toISOString()};const items=getProfiles();items.push(person);saveProfiles(items);localStorage.setItem('resume-tailor-v2:'+id,JSON.stringify({...structuredClone(defaults),profile:{...structuredClone(defaults.profile),...person.basics}}));renderProfiles();e.currentTarget.reset();openProfile(id);toast('已在新窗口创建独立档案')};renderProfiles();
function updateOwnerLabels(){const label=profileLabel();document.querySelector('#libraryOwner').textContent=label;document.querySelector('#libraryDialogOwner').textContent=label}const originalRenderProfiles=renderProfiles;renderProfiles=function(){originalRenderProfiles();updateOwnerLabels()};renderProfiles();
